const BOT_STRATEGIES = ["balanced", "all-cash", "all-equity"] as const;

function simulateChapter2(
  personaId: string,
  seed: string,
  strategy: (typeof BOT_STRATEGIES)[number],
  content: ContentBundle,
) {
  let s: GameState = createPlaythrough({ content, personaId, seed, chapterId: "ch2-first-job" });
  const decisions: { turn: number; type: string; payload: unknown }[] = [];

  for (let turn = 0; turn < 5; turn++) {
    // 0. Answer pending scams if any
    while (s.pendingScams.length > 0) {
      const pending = s.pendingScams[0]!;
      const scam = content.scams.scams.find((sc) => sc.id === pending.scamId);
      const isVictim = strategy === "all-equity" ? Math.random() < 0.35 : Math.random() < 0.15;
      const safeAction = scam?.actions.find((a) => !a.falls)?.id ?? "ignore";
      const fallAction = scam?.actions.find((a) => a.falls)?.id ?? "pay";
      const chosen = (isVictim ? fallAction : safeAction) as ScamAction;

      s = applyAction(
        s,
        { type: "scam_response", instanceId: pending.instanceId, response: chosen },
        content,
      );
      decisions.push({
        turn,
        type: isVictim ? "scam_fallen" : "scam_spotted",
        payload: { scamId: pending.scamId, response: chosen },
      });
    }

    // 1. Pay tasks
    for (const task of s.tasks) {
      if (task.status === "open" || task.status === "late") {
        const toPay = Math.min(task.amount - task.paid, s.cash);
        if (toPay > 0) {
          s = applyAction(s, { type: "pay_task", taskId: task.taskId, amount: toPay }, content);
          decisions.push({
            turn,
            type: "task_paid",
            payload: { taskId: task.taskId, amount: toPay },
          });
        }
      }
    }

    // 2. Strategy allocations
    if (strategy === "balanced") {
      if (turn === 0 && s.cash >= 3000_00) {
        s = applyAction(
          s,
          { type: "sip_start", optionId: "equity-fund", amountPerMonth: 3000_00 },
          content,
        );
        decisions.push({
          turn,
          type: "sip_start",
          payload: { optionId: "equity-fund", amountPerMonth: 3000_00 },
        });
      }
      if (s.cash > 25000_00) {
        const investAmount = 10000_00;
        s = applyAction(s, { type: "invest", optionId: "gold", amount: investAmount }, content);
        decisions.push({
          turn,
          type: "invest",
          payload: { optionId: "gold", amount: investAmount },
        });
      }
    } else if (strategy === "all-equity") {
      if (s.cash > 5000_00) {
        const investAmount = s.cash - 2000_00;
        s = applyAction(
          s,
          { type: "invest", optionId: "equity-fund", amount: investAmount },
          content,
        );
        decisions.push({
          turn,
          type: "invest",
          payload: { optionId: "equity-fund", amount: investAmount },
        });
      }
    }

    // 3. Turn advance
    const outcome = advanceTurn(s, content);
    s = outcome.state;

    // Record toss
    decisions.push({
      turn,
      type: "market_toss",
      payload: { marketState: outcome.tossResult.marketState },
    });

    // Answer any scams that arrived in this turn's toss
    while (s.pendingScams.length > 0) {
      const pending = s.pendingScams[0]!;
      const scam = content.scams.scams.find((sc) => sc.id === pending.scamId);
      const isVictim = strategy === "all-equity" ? Math.random() < 0.35 : Math.random() < 0.15;
      const safeAction = scam?.actions.find((a) => !a.falls)?.id ?? "ignore";
      const fallAction = scam?.actions.find((a) => a.falls)?.id ?? "pay";
      const chosen = (isVictim ? fallAction : safeAction) as ScamAction;

      s = applyAction(
        s,
        { type: "scam_response", instanceId: pending.instanceId, response: chosen },
        content,
      );
      decisions.push({
        turn,
        type: isVictim ? "scam_fallen" : "scam_spotted",
        payload: { scamId: pending.scamId, response: chosen },
      });
    }
  }

  const result = endChapter(s, content);
  decisions.push({
    turn: 5,
    type: "chapter_end",
    payload: { healthScore: result.healthScore, passed: result.passed },
  });

  return { state: s, result, decisions };
}

async function main() {
  console.log("Loading game content...");
  const loaded = await loadContent();
  if (!loaded.ok) {
    throw new Error("Failed to load content bundle");
  }
  const content = loaded.bundle;

  const orgId = "00000000-0000-0000-0000-000000000001";
  const adminId = "00000000-0000-0000-0000-000000000002";

  const sqlStatements: string[] = [
    "-- Generated by scripts/seed.ts for demo NGO & student cohort",
    "BEGIN;",
    `-- Clean previous demo data if any`,
    `DELETE FROM public.organizations WHERE id = '${orgId}';`,
    "",
    `-- 1. Create Demo NGO Organization`,
    `INSERT INTO public.organizations (id, name, admin_user_id, settings)`,
    `VALUES ('${orgId}', 'Hyderabad Youth Empowerment Trust', '${adminId}', '{"codeExpiryDays": 30}'::jsonb);`,
    "",
    `-- 2. Create Admin Profile`,
    `INSERT INTO public.profiles (user_id, role, org_id, username, nickname, player_id, locale, has_recovery_email)`,
    `VALUES ('${adminId}', 'ngo_admin', '${orgId}', 'hyderabad_admin', 'Kavitha Facilitator', 'TL-ADMIN', 'en', true);`,
    "",
  ];

  console.log(`Simulating cohort of ${STUDENT_NAMES.length} students...`);

  for (let i = 0; i < STUDENT_NAMES.length; i++) {
    const fullName = STUDENT_NAMES[i] ?? "Student";
    const nickname = fullName.split(" ")[0] ?? "Student";
    const username = `student_${nickname.toLowerCase()}_${i + 1}`;
    const studentUserId = `00000000-0000-0000-0001-${String(i + 1).padStart(12, "0")}`;
    const codeId = `00000000-0000-0000-0002-${String(i + 1).padStart(12, "0")}`;
    const playthroughId = `00000000-0000-0000-0003-${String(i + 1).padStart(12, "0")}`;
    const last4 = String(1000 + i).slice(-4);
    const codeHash = `hash_${last4}_${i}`;
    const playerId = `TL-${String(10000 + i)}`;

    // Mindset pre answers simulation
    const preAnswers = {
      "q-gift": i % 3 === 0 ? "save-first" : "spend-less",
      "q-prize-wait": i % 2 === 0 ? "wait" : "today",
      "q-coin-toss": i % 4 === 0 ? "play-again" : "skip",
      "q-samosa": "inflation",
      "q-fd-belief": i % 2 === 0 ? "depends" : "safe-slow",
      "q-prize-message": "ignore",
    };
    const preScore = scoreMindset(preAnswers, content);
    const personaId = assignPersona(preScore.scores, content);

    // Bot strategy
    const strategy = BOT_STRATEGIES[i % BOT_STRATEGIES.length] ?? "balanced";
    const seed = `demo-seed-${i}-${Date.now()}`;
    const { state, result, decisions } = simulateChapter2(personaId, seed, strategy, content);

    // SQL generation
    sqlStatements.push(`-- Student ${i + 1}: ${nickname} (${personaId}, ${strategy})`);
    sqlStatements.push(
      `INSERT INTO public.profiles (user_id, role, org_id, username, nickname, avatar_id, player_id, locale, has_recovery_email)`,
      `VALUES ('${studentUserId}', 'student', '${orgId}', '${username}', '${nickname}', 'avatar-${(i % 5) + 1}', '${playerId}', 'en', false);`,
    );

    // Student code
    const codeStatus = i < 35 ? "active" : i < 38 ? "pending" : "expired";
    sqlStatements.push(
      `INSERT INTO public.student_codes (id, org_id, code_hash, code_last4, label, status, created_by, redeemed_by, redeemed_at)`,
      `VALUES ('${codeId}', '${orgId}', '${codeHash}', '${last4}', 'Batch 2026 - Seat ${i + 1}', '${codeStatus}', '${adminId}', ${codeStatus === "active" ? `'${studentUserId}'` : "NULL"}, ${codeStatus === "active" ? "NOW()" : "NULL"});`,
    );

    // Mindset response (pre)
    sqlStatements.push(
      `INSERT INTO public.mindset_responses (user_id, phase, answers, scores, persona_id, content_version)`,
      `VALUES ('${studentUserId}', 'pre', '${JSON.stringify(preAnswers)}'::jsonb, '${JSON.stringify(preScore.scores)}'::jsonb, '${personaId}', '${content.contentVersion}');`,
    );

    if (codeStatus === "active") {
      // Playthrough
      sqlStatements.push(
        `INSERT INTO public.playthroughs (id, user_id, persona_id, seed, content_version, current_chapter_id, status, state)`,
        `VALUES ('${playthroughId}', '${studentUserId}', '${personaId}', '${seed}', '${content.contentVersion}', 'ch2-first-job', 'completed', '${JSON.stringify(state).replace(/'/g, "''")}'::jsonb);`,
      );

      // Chapter result
      sqlStatements.push(
        `INSERT INTO public.chapter_results (playthrough_id, chapter_id, attempt, health_score, score_breakdown, report, passed)`,
        `VALUES ('${playthroughId}', 'ch2-first-job', 1, ${result.healthScore}, '${JSON.stringify(result.breakdown).replace(/'/g, "''")}'::jsonb, '${JSON.stringify(result.report).replace(/'/g, "''")}'::jsonb, ${result.passed});`,
      );

      // Decisions log
      for (const d of decisions) {
        sqlStatements.push(
          `INSERT INTO public.decisions (playthrough_id, chapter_id, turn, type, payload)`,
          `VALUES ('${playthroughId}', 'ch2-first-job', ${d.turn}, '${d.type}', '${JSON.stringify(d.payload).replace(/'/g, "''")}'::jsonb);`,
        );
      }
    }
    sqlStatements.push("");
  }

  sqlStatements.push("COMMIT;");

  const outputPath = resolve(__dirname, "../supabase/seed.sql");
  writeFileSync(outputPath, sqlStatements.join("\n"), "utf-8");
  console.log(`✔ Demo seed generated successfully at ${outputPath}`);
}

main().catch((err) => {
  console.error("Seed script failed:", err);
  process.exit(1);
});
